// One bomb a round clears every enemy near the player.
if scene.pressed("bomb") && scene.counter_value("bombs") > 0 {
    scene.add_to_counter("bombs", -1);
    for enemy in scene.in_class("enemy") {
        if distance(scene.object(&enemy).position(), player) <= 3.0 {
            scene.despawn(&enemy);
            scene.add_to_counter("kills", 1);
        }
    }
}

